diff --git a/packages/ui/src/lib/use-online.ts b/packages/ui/src/lib/use-online.ts
new file mode 100644
index 0000000..9f20403
--- /dev/null
+++ b/packages/ui/src/lib/use-online.ts
@@ -0,0 +1,22 @@
+import { useSyncExternalStore } from 'react';
+
+function subscribe(onChange: () => void): () => void {
+  window.addEventListener('online', onChange);
+  window.addEventListener('offline', onChange);
+  return () => {
+    window.removeEventListener('online', onChange);
+    window.removeEventListener('offline', onChange);
+  };
+}
+
+/**
+ * Whether the browser has a connection: false from the `offline` event until `online` brings it
+ * back on its own. TanStack Query pauses and retries its requests on the same two events.
+ */
+export function useOnline(): boolean {
+  return useSyncExternalStore(
+    subscribe,
+    () => navigator.onLine,
+    () => true,
+  );
+}
